Module PNSENBK.
Import PMS.
Import NEM.
Section K.
Context {bmK : BMode}.
Variables (E : ne_addrs) (L : heap_layout).
Abbreviation enc_at := (NEM.enc_at RSEGS E L PMSP.T3 PMSP.T4).

(* [comment removed for export] *)
Definition enc_hdr (M : word -> option byte) (ov osk : Z) (en : enc) : Prop :=
  L5.u64_at RSEGS M ov (ne_vt E) /\ L5.u64_at RSEGS M (ov + 8) osk /\ L5.u32_at RSEGS M (ov + 16) MAX_DEPTH
  /\ L5.u64_at RSEGS M (ov + 24) (en_b en)
  /\ L5.u64_at RSEGS M (ov + 40) (en_b en + ESZ * ecap (en_k en))
  /\ L5.u32_at RSEGS M (ov + 48) (en_depth en)
  /\ L5.defined M ov ESIZE
  /\ 0 <= en_k en <= EKMAX /\ 0 <= en_depth en <= en_n en /\ en_n en <= ecap (en_k en)
  /\ (en_k en = 0 -> en_b en = 0)
  /\ (0 < en_k en -> en_b en mod 8 = 0 /\ L5.defined M (en_b en) (ESZ * ecap (en_k en)) /\ block_range L (en_b en) (ESZ * ecap (en_k en))).

