(* [comment removed for export] *)
Lemma enc_hdr_room (M M' : word -> option byte) ov osk eb ek m d d' :
  enc_at M ov osk (ENC eb ek m d) -> mem_grows M M' -> 0 <= ov -> ov + 56 <= 2 ^ 64 ->
  L5C.agree_on M M' ov 48 -> L5.u32_at RSEGS M' (ov + 48) d' ->
  0 <= d' <= m + 1 -> m + 1 <= ecap ek ->
  enc_hdr M' ov osk (ENC eb ek (m + 1) d').
