(* [comment removed for export] *)
Lemma enc_grow (M M' : word -> option byte) ov osk eb ek m d d' B :
  enc_at M ov osk (ENC eb ek m d) -> mem_grows M M' -> 0 <= ov -> ov + 56 <= 2 ^ 64 ->
  L5C.agree_on M M' ov 24 ->
  L5.u64_at RSEGS M' (ov + 24) B -> L5.u64_at RSEGS M' (ov + 32) (B + ESZ * (m + 1)) -> L5.u64_at RSEGS M' (ov + 40) (B + ESZ * ecap (ek + 1)) ->
  L5.u32_at RSEGS M' (ov + 48) d' -> 0 <= d' <= m + 1 -> m + 1 <= ecap (ek + 1) -> ek + 1 <= EKMAX ->
  B mod 8 = 0 -> L5.defined M' B (ESZ * ecap (ek + 1)) -> block_range L B (ESZ * ecap (ek + 1)) ->
