  L5.u64_at RSEGS M' ov (ne_vt E) -> L5.u64_at RSEGS M' (ov + 8) osk -> L5.u32_at RSEGS M' (ov + 16) MAX_DEPTH ->
  L5.u64_at RSEGS M' (ov + 24) B -> L5.u64_at RSEGS M' (ov + 32) (B + ESZ * n') -> L5.u64_at RSEGS M' (ov + 40) (B + ESZ * ecap k') ->
  L5.u32_at RSEGS M' (ov + 48) d' -> L5.defined M' ov ESIZE -> 0 <= k' <= EKMAX -> 0 <= d' <= n' -> n' <= ecap k' -> (k' = 0 -> B = 0) ->
  (0 < k' -> B mod 8 = 0 /\ L5.defined M' B (ESZ * ecap k') /\ block_range L B (ESZ * ecap k')) ->
  enc_at M' ov osk (ENC B k' n' d').
Proof.
