Section Loop.
Variable M : word -> option byte.
Variables (S p e : Z).
Hypothesis RO : L5.img_clear M 65536 814272.
Hypothesis DEF : L5.defined M p (e - p).
Hypothesis HS : 140735332483168 <= S <= 2 ^ 47.
Hypothesis Hp : 0 <= p.
Hypothesis He : e <= 2 ^ 47.
Hypothesis Hn : e - p <= 2 ^ 26.

Definition goal_from (fx : FPState) (R : bvmap 5 word) (pc : Z) : Prop :=
  exists fx' R', msteps RSEGS (st fx R pc M) (st fx' R' 0x46aa4 M) /\ getr R' (reg 2) = Z_to_bv 64 (S - 96) /\ (forall k, In k KL -> getr R' (reg k) = getr R (reg k)).

